"#!/usr/bin/env bash\nset -euo pipefail\n\n# Quick fix for CI binary resolution issues\n# This ensures CI uses local souc binary when available\n\nROOT_DIR=\"$(cd \"$(dirname \"\${BASH_SOURCE[0]}\")/..\" && pwd)\"\ncd \"$ROOT_DIR\"\n\n# Check if local souc exists\nLOCAL_SOUC=\"./souc\"\nif [ -x \"$LOCAL_SOUC\" ]; then\n    echo \"Using local souc binary: $LOCAL_SOUC\"\n    echo \"SOUC_BIN=$(realpath \"$LOCAL_SOUC\")\" >> \"$GITHUB_ENV\"\n    exit 0\nfi\n\n# Check artifacts\nARTIFACT_SOUC=\"artifacts/omega/souc-bin/souc-linux-x86_64\"\nif [ -x \"$ARTIFACT_SOUC\" ]; then\n    echo \"Using artifact souc binary: $ARTIFACT_SOUC\"\n    echo \"SOUC_BIN=$(realpath \"$ARTIFACT_SOUC\")\" >> \"$GITHUB_ENV\"\n    exit 0\nfi\n\n# Fallback to resolution script\nchmod +x scripts/omega/omega_resolve_souc_bin.sh\nSOUC_BIN=\"$( \\\n    SOUNIO_SOUC_VERSION=1.0.0-beta.5 \\\n    OMEGA_SOUC_REQUIRE_PINNED=1 \\\n    OMEGA_SOUC_ALLOW_LOCAL_FALLBACK=1 \\\n    scripts/omega/omega_resolve_souc_bin.sh --print-path \\\n)\"\necho \"Using resolved souc binary: $SOUC_BIN\"\necho \"SOUC_BIN=$SOUC_BIN\" >> \"$GITHUB_ENV\"\n"